// Package argparse is a small command-line argument parser.
package argparse

import (
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

// ErrHelp is returned by Parse when -h or --help is given.
var ErrHelp = errors.New("help requested")

type flag struct {
	name, usage, def string
	b                *bool
	s                *string
}

type Parser struct {
	name  string
	flags []*flag
	args  []string
}

func New(name string) *Parser { return &Parser{name: name} }

// Bool defines a boolean flag, false unless given.
func (p *Parser) Bool(name, usage string) *bool {
	v := new(bool)
	p.flags = append(p.flags, &flag{name: name, usage: usage, b: v})
	return v
}

// String defines a flag that takes a value, as --name value or --name=value.
func (p *Parser) String(name, def, usage string) *string {
	v := &def
	p.flags = append(p.flags, &flag{name: name, usage: usage, def: def, s: v})
	return v
}

// Args returns the positional arguments found by Parse.
func (p *Parser) Args() []string { return p.args }

// Parse reads argv, which should not include the program name.
// Everything after a bare "--" is positional.
func (p *Parser) Parse(argv []string) error {
	for i := 0; i < len(argv); i++ {
		a := argv[i]
		if a == "--" {
			p.args = append(p.args, argv[i+1:]...)
			break
		}
		if len(a) < 2 || a[0] != '-' {
			p.args = append(p.args, a)
			continue
		}
		name, val, hasVal := strings.Cut(strings.TrimLeft(a, "-"), "=")
		if name == "h" || name == "help" {
			return ErrHelp
		}
		f := p.lookup(name)
		switch {
		case f == nil:
			return fmt.Errorf("unknown flag: %s", a)
		case f.b != nil:
			*f.b = true
			if hasVal {
				b, err := strconv.ParseBool(val)
				if err != nil {
					return fmt.Errorf("invalid boolean for --%s: %q", name, val)
				}
				*f.b = b
			}
		case hasVal:
			*f.s = val
		case i+1 < len(argv):
			i++
			*f.s = argv[i]
		default:
			return fmt.Errorf("flag --%s needs a value", name)
		}
	}
	return nil
}

func (p *Parser) lookup(name string) *flag {
	for _, f := range p.flags {
		if f.name == name {
			return f
		}
	}
	return nil
}

// Usage writes a help message built from the flag definitions.
func (p *Parser) Usage(w io.Writer) {
	fmt.Fprintf(w, "Usage: %s [flags] [args...]\n\nFlags:\n", p.name)
	for _, f := range p.flags {
		name, usage := "--"+f.name, f.usage
		if f.s != nil {
			name += " <value>"
			if f.def != "" {
				usage += fmt.Sprintf(" (default %q)", f.def)
			}
		}
		fmt.Fprintf(w, "  %-24s %s\n", name, usage)
	}
	fmt.Fprintf(w, "  %-24s %s\n", "-h, --help", "show this help")
}
